CertHub.labFiles = ["labs-blueteam.js","labs-cloud.js","labs-data-ai.js","labs-foundations.js","labs-grc.js","labs-more.js","labs-neteng.js","labs-network.js","labs-secadmin.js","labs-software.js","labs-sysadmin.js"];
CertHub.registerLabs([{"id":"lab-splunk-siem","title":"Build a Splunk SIEM and detect brute-force logons","track":"Blue team","level":"Intermediate","minutes":240,"cost":"Free (Splunk Enterprise 60-day trial, which becomes Splunk Free afterwards; needs a free splunk.com account)","summary":"Install Splunk Enterprise on Ubuntu, forward Windows Security logs and Linux auth.log with Universal Forwarders, then write SPL searches, a dashboard panel and a scheduled alert for failed logons, a success after many failures, and a new local admin.","stepCount":15},{"id":"lab-wazuh","title":"Deploy Wazuh XDR/SIEM, catch SSH brute force and tune a rule","track":"Blue team","level":"Intermediate","minutes":240,"cost":"Free (open source)","summary":"Install Wazuh all-in-one on Ubuntu with the official assisted installer, enroll Windows and Linux agents, set up file integrity monitoring, trigger an SSH brute-force alert from another lab VM, explore the MITRE ATT&CK view and tune one noisy rule.","stepCount":13},{"id":"lab-sysmon-detection","title":"Install Sysmon, generate benign activity and write a detection","track":"Blue team","level":"Intermediate","minutes":180,"cost":"Free","summary":"Install Sysinternals Sysmon with the SwiftOnSecurity community config, read process, network and file events in Event Viewer and PowerShell, run harmless test activity (an encoded PowerShell 'hello' and a scheduled task), find it in the logs and write a Sigma rule plus matching Splunk and Wazuh searches.","stepCount":14},{"id":"lab-phishing-analysis","title":"Triage a phishing email from raw headers to verdict","track":"Blue team","level":"Beginner","minutes":120,"cost":"Free","summary":"Open the raw source of a real email you received, trace its Received hops, read SPF, DKIM and DMARC results, check the sender domain's DNS records with dig, look up URLs safely on urlscan.io and VirusTotal without clicking, defang the IOCs and write a triage ticket with a verdict and actions.","stepCount":13},{"id":"lab-pcap-investigation","title":"Investigate a malware traffic PCAP and write an incident report","track":"Blue team","level":"Intermediate","minutes":180,"cost":"Free","summary":"Analyze a published training PCAP from malware-traffic-analysis.net in an isolated VM: use Wireshark filters for HTTP, TLS SNI and DNS, identify the infected host's IP, MAC, hostname and user from DHCP, NBNS and Kerberos, extract IOCs and write an incident report.","stepCount":14},{"id":"lab-vuln-management","title":"Run a full vulnerability management cycle with Greenbone/OpenVAS","track":"Blue team","level":"Intermediate","minutes":360,"cost":"Free","summary":"Run Greenbone Community Edition (OpenVAS) in its official containers, scan a deliberately vulnerable Metasploitable 2 VM on an isolated network, validate two findings, prioritize with CVSS, EPSS and CISA KEV, write a remediation plan with owners and SLAs, then mitigate one finding and rescan to prove closure.","stepCount":14},{"id":"lab-incident-response","title":"Run a ransomware tabletop, write the playbook and handle a simulated incident","track":"Blue team","level":"Intermediate","minutes":300,"cost":"Free","summary":"Plan and run a ransomware tabletop exercise, write an incident response playbook based on NIST SP 800-61 with roles, decision points, communication templates and evidence handling, then simulate a detection in your lab SIEM and write a full incident report with a timeline.","stepCount":14},{"id":"lab-memory-forensics","title":"Analyze Windows memory images with Volatility 3","track":"Blue team","level":"Advanced","minutes":300,"cost":"Free","summary":"Install Volatility 3 in a Python virtual environment, analyze a public training memory image with windows.info, pslist, pstree, psscan, netscan, cmdline and malfind to find the suspicious process, then capture RAM from your own Windows VM with WinPmem and analyze it.","stepCount":14},{"id":"lab-disk-forensics","title":"Image a drive, keep chain of custody and recover a deleted file with Autopsy","track":"Blue team","level":"Intermediate","minutes":240,"cost":"Free","summary":"Create a small evidence disk and plant files, image it with dc3dd behind a software write-block, verify SHA-256 hashes, fill in a chain-of-custody form, recover a deleted file with Sleuth Kit and Autopsy, build a timeline and write findings, including why order of volatility matters.","stepCount":13},{"id":"lab-threat-intel","title":"Build a Salt Typhoon threat intel brief with ATT&CK Navigator","track":"Blue team","level":"Intermediate","minutes":240,"cost":"Free","summary":"Read the CISA/FBI joint advisory on PRC state-sponsored (Salt Typhoon) compromises of telecom and other networks, map its TTPs to MITRE ATT&CK in an ATT&CK Navigator layer, list IOCs and which of your lab logs would show them, and write a one-page intel brief with recommended defenses for a manager.","stepCount":12},{"id":"lab-cyberchef-decoding","title":"Decode obfuscated data with CyberChef","track":"Blue team","level":"Beginner","minutes":90,"cost":"Free","summary":"Run CyberChef offline and decode samples you create yourself: Base64, hex, URL encoding, PowerShell UTF-16LE, gzip plus Base64 and XOR with a known key, then extract and defang URLs and IPs, save a reusable recipe and relate it to triaging suspicious scripts.","stepCount":12},{"id":"lab-cloud-aws-account-safety","title":"Secure a new AWS account before you build anything: root MFA, zero-spend budget and an Identity Center admin","track":"Cloud computing","level":"Beginner","minutes":90,"cost":"Free. Nothing in this lab is billable: MFA, AWS Budgets (two budgets without actions), IAM Identity Center, AWS Organizations and CloudTrail event history cost nothing. Doing this first is what keeps every later lab from surprising you with a bill.","summary":"Do the first hour of work every cloud engineer does on a new AWS account: protect the root user with MFA, confirm it has no access keys, turn on billing alerts, create a zero-spend budget and a small monthly budget, create a day-to-day admin identity in IAM Identity Center, sign in to the AWS CLI with short-lived credentials, and audit the result.","stepCount":12},{"id":"lab-cloud-iam-least-privilege","title":"Write, test and tighten least-privilege IAM policies for an application role","track":"Cloud computing","level":"Intermediate","minutes":120,"cost":"Free. IAM, STS, the IAM policy simulator, IAM Access Analyzer policy validation and an empty S3 bucket with a few small text files cost nothing (S3 storage of a few KB is within any free offer). Delete the bucket at the end anyway.","summary":"A reporting job needs to read and write files under one prefix of one S3 bucket and nothing else. Write that policy, catch mistakes with IAM Access Analyzer policy validation, prove it with the policy simulator, put it on a role and test it with real temporary credentials, then add a permissions boundary and an explicit deny to see how AWS evaluates policies, and use last-accessed data to trim unused permissions.","stepCount":11},{"id":"lab-cloud-s3-static-site","title":"Host a static website on Amazon S3 and control access with Block Public Access and bucket policies","track":"Cloud computing","level":"Beginner","minutes":75,"cost":"Free or a fraction of a cent: a few KB of storage and a handful of requests are covered by the AWS Free plan credits or the legacy S3 free tier. Costs only grow if you leave a public bucket up and it gets traffic, so delete it the same day.","summary":"Upload a small website to S3, turn on static website hosting, watch Block Public Access stop it from being public, deliberately open only that bucket for reading with a bucket policy, test the site, share a private file safely with a pre-signed URL instead, then lock everything back down and delete the bucket.","stepCount":10},{"id":"lab-cloud-ec2-basics","title":"Launch, secure, snapshot and terminate an EC2 web server on the Free Tier","track":"Cloud computing","level":"Beginner","minutes":120,"cost":"Free or a few cents if you finish the same day: use a free-tier-eligible instance type (the lab shows you how to list them) and an 8 GB gp3 volume. The public IPv4 address is billed at about 0.005 USD per hour unless your free offer covers it, and snapshots cost about 0.05 USD per GB-month, so terminate the instance and delete the snapshot at the end. A stopped instance still pays for its EBS volume.","summary":"Launch an Amazon Linux 2023 instance from the AWS CLI with a key pair, a security group that allows SSH and HTTP only from your IP, IMDSv2 required and an encrypted gp3 root volume; install a web server with user data; see how stop and start change the public IP; take an EBS snapshot; then terminate everything and prove nothing is left billing.","stepCount":12},{"id":"lab-cloud-vpc-subnets","title":"Design a two-AZ VPC with public and private subnets, reach a private instance without a NAT gateway","track":"Cloud computing","level":"Intermediate","minutes":150,"cost":"Free or a few cents if you clean up the same day: the VPC, subnets, route tables, internet gateway, S3 gateway endpoint and EC2 Instance Connect Endpoint have no hourly charge, and the one free-tier-eligible instance has no public IP. Do NOT create a NAT gateway: it costs about 0.045 USD per hour plus a per-GB processing charge in us-east-1 (over 30 USD a month even when idle). The VPC wizard offers one by default; you will turn it off.","summary":"Plan an address layout, build a VPC across two Availability Zones with public and private subnets using the console wizard (with NAT gateways set to None and a free S3 gateway endpoint), inspect the route tables with the CLI, launch a private instance with no public IP, reach it through an EC2 Instance Connect Endpoint, prove it has no internet access but can reach S3, break and fix a security group rule, and delete the whole VPC.","stepCount":11},{"id":"lab-cloud-cloudwatch","title":"Monitor with Amazon CloudWatch: logs, metric filters, alarms, email alerts and a billing alarm","track":"Cloud computing","level":"Intermediate","minutes":100,"cost":"Free within the CloudWatch free tier if you follow the steps: a few KB of logs, one custom metric, up to three alarms, one dashboard and a few SNS emails. Logs Insights charges per GB scanned (fractions of a cent here). Set log retention to one day and delete everything at the end.","summary":"Create an SNS topic with an email subscription, send application log lines to a CloudWatch Logs group with short retention, turn ERROR lines into a metric with a metric filter, alarm on it and receive the email, query the logs with Logs Insights, build a small dashboard, and add a billing alarm on estimated charges as a second cost guardrail.","stepCount":11},{"id":"lab-cloud-azure-governance","title":"Azure governance basics: free account guardrails, resource groups, tags, RBAC, Azure Policy and locks","track":"Cloud computing","level":"Beginner","minutes":120,"cost":"Free. Resource groups, tags, Microsoft Entra ID users, role assignments, custom roles, built-in Azure Policy assignments, resource locks and virtual networks have no charge. The only resources created are empty virtual networks, which are free. Set the budget first anyway.","summary":"Set up an Azure free account safely (spending limit, budget alert), then practise the governance tools every Azure administrator uses: a tagged resource group, a test user with the built-in Reader role and a custom least-privilege role, Azure Policy assignments that deny resources in the wrong region or without a cost-center tag, a delete lock, and the activity log. Finish by removing every assignment, role, user and resource group.","stepCount":13},{"id":"lab-cloud-azure-storage-vm","title":"Azure Storage and VMs: blob tiers, lifecycle rules, SAS, a Linux VM, snapshots and cost cleanup","track":"Cloud computing","level":"Intermediate","minutes":150,"cost":"Low and usually covered by free-account credit or 12-month free services: a Standard_LRS storage account with a few KB of blobs, and one small Linux VM of a size listed as free for your account (for example Standard_B1s) for a few hours. A Standard public IP, a disk snapshot and moving tiny blobs to Cool, Cold or Archive cost fractions of a cent. A VM that is only stopped, not deallocated, keeps billing for compute. Delete the resource group the same day.","summary":"Create a locked-down storage account, upload blobs with your Entra ID identity (no account keys), move blobs between Hot, Cool, Cold and Archive tiers, write a lifecycle management policy, recover a deleted blob with soft delete, share one file with a short-lived user delegation SAS, then deploy a small Linux VM with an NSG that allows only your IP and auto-shutdown, snapshot its disk, learn the difference between stopped and deallocated, review costs by tag and delete everything.","stepCount":12},{"id":"lab-cloud-iac-deploy","title":"Infrastructure as code on AWS: deploy, change, detect drift and destroy with Terraform and CloudFormation","track":"Cloud computing","level":"Intermediate","minutes":150,"cost":"Free. The stacks create only no-charge resources while idle: an empty S3 bucket with versioning, encryption and Block Public Access, and an SNS topic with no subscribers. Terraform, cfn-lint and Checkov are free open-source tools. Destroy both stacks at the end.","summary":"Define the same small, secure stack (an S3 bucket with Block Public Access, versioning and encryption, plus an SNS topic) twice: with Terraform and with AWS CloudFormation. Run the full workflow for each: validate, plan or change set, deploy, read outputs, preview a replacement, cause drift by changing a setting by hand, detect and fix it, scan the code for misconfigurations, and destroy everything.","stepCount":12},{"id":"lab-cloud-pricing-responsibility","title":"Shared responsibility and cost estimation with the AWS and Azure pricing calculators (no account needed)","track":"Cloud computing","level":"Beginner","minutes":120,"cost":"Free. No cloud account is needed: the AWS Pricing Calculator, the Azure Pricing Calculator and the Azure Retail Prices API are public. Nothing is deployed.","summary":"Map who is responsible for what across IaaS, PaaS, serverless and SaaS, then estimate the monthly cost of the same small web application on AWS and on Azure with the official pricing calculators, compare on-demand with Savings Plans and reservations, pull live list prices from the public Azure Retail Prices API, and write a one-page cost and responsibility memo with concrete savings recommendations.","stepCount":10},{"id":"lab-data-sql-sqlite","title":"Answer business questions with SQL on a public sample database in SQLite","track":"Data & AI","level":"Beginner","minutes":90,"cost":"Free. SQLite and the Chinook sample database are free and run entirely on your own machine; no account or cloud service is needed.","summary":"Download the public Chinook sample database (a digital music store with customers, invoices, tracks and employees), explore its schema with the sqlite3 shell, and answer real business questions with filters, joins, grouping, common table expressions and window functions. Finish by checking data quality, adding an index, and exporting a result to CSV for a report.","stepCount":11},{"id":"lab-data-cleaning-pandas","title":"Clean a messy dataset with Python pandas and log every data quality decision","track":"Data & AI","level":"Beginner","minutes":90,"cost":"Free. Python and pandas run on your own machine, or use Google Colab's free tier in a browser (a Google account is needed for Colab; do not upload real personal data to it).","summary":"Create a deliberately messy customer orders file, profile it with pandas, and fix the problems analysts meet every week: inconsistent column names and text, duplicates, missing values, unparseable dates, currency strings, invalid emails and outliers. Mask personal data, validate the result with explicit rules, and write a data quality log.","stepCount":11},{"id":"lab-data-stats-ab-test","title":"Descriptive statistics and an A/B test readout with Python","track":"Data & AI","level":"Intermediate","minutes":120,"cost":"Free. Everything runs locally in Python (or in a free Google Colab notebook) on simulated data.","summary":"Simulate a website A/B test with a known effect, describe the data (center, spread, shape and percentiles), check the experiment is healthy with a sample ratio mismatch test, then test conversion with a two-proportion z-test and revenue with a non-parametric test. Compute confidence intervals and the sample size you would have needed, and write a one-page readout a product manager can act on.","stepCount":10},{"id":"lab-data-dashboard-governance","title":"Build a sales dashboard in Power BI Desktop or Looker Studio and govern it with a checklist","track":"Data & AI","level":"Intermediate","minutes":150,"cost":"Free. Power BI Desktop is a free Windows download; Looker Studio is free in a browser with a Google account. Do not use Power BI 'Publish to web' or Looker Studio public sharing: both make the report readable by anyone with the link.","summary":"Turn a clean dataset into a one-page dashboard with KPIs, a trend, a breakdown and filters, using Power BI Desktop (Windows) or Looker Studio (any browser). Then apply a data governance checklist: owner and steward, data dictionary, source and refresh, classification, access and row-level security, retention, quality checks and change log.","stepCount":10},{"id":"lab-ai-responsible-assessment","title":"Run a responsible-AI impact assessment and a fairness check on a sample hiring model","track":"Data & AI","level":"Intermediate","minutes":150,"cost":"Free. The assessment is a document, and the fairness measurement runs locally in Python with the open-source Fairlearn library on synthetic data.","summary":"Take a realistic high-risk use case, an AI system that ranks job applicants, and assess it the way a responsible-AI review board would: describe intended use and stakeholders, identify harms against the six Microsoft responsible AI principles and the NIST AI RMF, measure group fairness on a synthetic model with Fairlearn, and decide on mitigations, human oversight, transparency and monitoring before a go or no-go recommendation.","stepCount":10},{"id":"lab-ai-azure-language-vision","title":"Analyze text and images with Azure AI Language and Azure AI Vision on the free F0 tier","track":"Data & AI","level":"Beginner","minutes":90,"cost":"Free on the F0 tier: Azure AI Language F0 and Azure AI Vision F0 have monthly free transaction limits (you get HTTP 429 errors rather than charges when you hit them). An Azure account needs a payment card. Only one F0 resource of each kind is allowed per subscription. If F0 is unavailable and you pick S0 or S1 instead, every call is billed, so check the pricing pages first and delete the resources the same day.","summary":"Create Azure AI Language and Azure AI Vision resources on the free tier with the Azure CLI, keep keys out of files, and call the REST APIs to detect language, analyze sentiment with opinion mining, extract key phrases, redact personal data, tag objects in a photo and read printed text. Check usage metrics, rotate a key, and delete and purge everything.","stepCount":10},{"id":"lab-ai-prompt-grounding","title":"Prompt engineering and grounding with Azure OpenAI in Foundry, or a free local open model","track":"Data & AI","level":"Intermediate","minutes":150,"cost":"Two paths. Local path: free, runs an open model with Ollama on your own machine (needs about 8 GB of RAM; no account). Azure path: Azure OpenAI models have no free tier; they are billed per token (a lab like this typically costs cents with a small model such as gpt-4o-mini, but check the pricing page), the Azure free account credit can cover it, and some models or regions may require an access request or quota approval. Set a budget alert before starting and delete the resource at the end.","summary":"Write one small Python script that talks to either a local open model through Ollama or an Azure OpenAI deployment, then improve its answers step by step: system message, clear instructions and delimiters, structured JSON output, few-shot examples and temperature. Ground the model in a policy document so it answers only from sources with citations and says 'I don't know' otherwise, and test that it resists instructions hidden inside a document.","stepCount":9},{"id":"lab-ai-rag-search","title":"Build a small retrieval-augmented generation (RAG) app with Azure AI Search free tier or a local vector store","track":"Data & AI","level":"Advanced","minutes":180,"cost":"Local path: free (Ollama embeddings and chat on your machine). Azure path: Azure AI Search Free tier costs nothing (one free service per subscription, 50 MB storage, 3 indexes, no SLA, and it can be unavailable in busy regions); generation uses either the local model or the Azure OpenAI deployment from lab-ai-prompt-grounding, which is billed per token. Never choose the Basic or higher Search tier by accident: those bill hourly even when idle.","summary":"Write a small help desk knowledge base, split it into chunks, and build retrieval two ways: vector search over local embeddings with numpy, and keyword (BM25) search in an Azure AI Search free-tier index. Feed the top chunks to a model with a grounded prompt that cites sources, then measure retrieval hit rate on a small question set and compare the two retrievers.","stepCount":10},{"id":"lab-ai-eval-safety","title":"Evaluate model output quality and test safety filters with Azure AI Content Safety or Llama Guard","track":"Data & AI","level":"Advanced","minutes":150,"cost":"Local path: free (Ollama with llama3.2 and llama-guard3). Azure path: Azure AI Content Safety has a free F0 tier with a monthly transaction limit; if you evaluate an Azure OpenAI deployment, those calls are billed per token. Set a budget alert first and delete resources when done.","summary":"Build a small evaluation set for the grounded assistant from earlier labs (in-scope questions with expected facts, out-of-scope questions and prompt injection attempts), score answers automatically for correctness, refusal behavior and citations, and add an LLM-as-judge groundedness score. Then put a safety layer in front: classify inputs and outputs with Azure AI Content Safety (text analysis and Prompt Shields) or Llama Guard locally, and measure false positives.","stepCount":10},{"id":"lab-gcp-account-safety","title":"Secure a Google Cloud free tier account: budget alerts, billing export to BigQuery and least-privilege IAM","track":"Cloud computing","level":"Beginner","minutes":90,"cost":"Free. Budgets, IAM, service accounts and Cloud Shell cost nothing, and the BigQuery billing export stays far inside BigQuery's free monthly storage and query allowance. New customers get Free Trial credit for a limited time plus Always Free usage limits; a budget only sends alerts, it does not stop spending.","summary":"Do the first hour of work on a new Google Cloud account: protect the Google account with 2-Step Verification, create a dedicated lab project, set a small budget with actual and forecast alerts, export billing data to BigQuery and query it, and practise least privilege with predefined roles and a keyless service account you impersonate to prove what it can and cannot do.","stepCount":10},{"id":"lab-gcp-cloud-run-storage","title":"Deploy a container to Cloud Run and store files in Cloud Storage with gcloud, then delete it all","track":"Cloud computing","level":"Intermediate","minutes":120,"cost":"Free tier if you follow the steps: Cloud Run includes a monthly free allowance of requests and CPU and memory time, Cloud Build a daily allowance of build minutes, Artifact Registry a small free storage amount, and Cloud Storage 5 GB-months of Standard storage in us-east1, us-west1 or us-central1. Other regions or storage classes can bill. Set --max-instances=1, stay in us-central1, and delete everything at the end.","summary":"Deploy Google's sample container to Cloud Run, then build and deploy your own small Flask app from source, roll out a new revision and roll back. Lock the service down to authenticated callers. Create a Cloud Storage bucket with uniform access and public access prevention, add versioning and a lifecycle rule, and finish by deleting the services, images and buckets.","stepCount":10},{"id":"lab-gcp-compute-vpc-monitoring","title":"Run an e2-micro VM in a custom VPC with firewall rules and a Cloud Monitoring alert, then delete it","track":"Cloud computing","level":"Intermediate","minutes":120,"cost":"Mostly free: the Compute Engine free tier covers one e2-micro VM per month in us-west1, us-central1 or us-east1 with up to 30 GB of standard persistent disk. Other machine types, regions or disk types bill. An in-use external IPv4 address may be charged a small hourly fee, so check the VPC pricing page, or use the no-external-IP option in step 5. Cloud Monitoring metrics for VMs and email alerts are free. Delete everything at the end.","summary":"Build a custom-mode VPC with one subnet, write firewall rules that allow SSH only from Identity-Aware Proxy and HTTP only from your own IP, launch a free tier e2-micro running nginx, test rule priority with a deny rule, create a CPU alert policy with an email channel, trigger it with a load test, and then delete every resource.","stepCount":11},{"id":"lab-home-lab","title":"Build a home security lab with VirtualBox","track":"Foundations","level":"Beginner","minutes":180,"cost":"Free (VirtualBox, Ubuntu Server and Windows evaluation ISOs)","summary":"Build a small virtual lab: an Ubuntu Server 24.04 VM and a Windows evaluation VM on an isolated host-only network, with a NAT adapter for updates, a written IP plan, snapshots and a network diagram. Most other labs build on this one.","stepCount":13},{"id":"lab-linux-cli","title":"Linux command line for security work","track":"Foundations","level":"Beginner","minutes":90,"cost":"Free","summary":"Use the Linux commands a security analyst reaches for every day: manage users and groups, set permission bits, use sudo safely, find risky files, triage SSH logs with grep and awk, list listening ports and apply updates.","stepCount":12},{"id":"lab-linux-hardening","title":"Harden an Ubuntu 24.04 server","track":"Foundations","level":"Intermediate","minutes":150,"cost":"Free","summary":"Take a default Ubuntu 24.04 server to a hardened baseline: automatic security updates, a named admin account, key-only SSH with root login off, a default-deny firewall, fail2ban and fewer services, measured before and after with Lynis.","stepCount":12},{"id":"lab-windows-hardening","title":"Apply a Windows security baseline and audit logons","track":"Foundations","level":"Beginner","minutes":120,"cost":"Free (Windows evaluation)","summary":"Set password and lockout policy, confirm Microsoft Defender and the firewall with PowerShell, turn on logon auditing with auditpol, find Event IDs 4624, 4625 and 4720 in Event Viewer and with Get-WinEvent, remove SMBv1, and compare your settings to a published baseline.","stepCount":13},{"id":"lab-hashing-integrity","title":"Hashing, signed downloads and file integrity monitoring","track":"Foundations","level":"Beginner","minutes":90,"cost":"Free","summary":"Hash files on Linux and Windows, verify a real Ubuntu download with SHA256SUMS and its GPG signature, see the avalanche effect, compare salted password hashes, and set up AIDE to detect a changed system file.","stepCount":13},{"id":"lab-pki-openssl","title":"Build a two-tier PKI with OpenSSL and serve HTTPS","track":"Foundations","level":"Intermediate","minutes":150,"cost":"Free","summary":"Create a root CA and an intermediate CA with OpenSSL, issue a server certificate with SAN entries, serve it from nginx, trust the root on a client, inspect the chain with openssl s_client and a browser, then revoke the certificate and publish a CRL.","stepCount":12},{"id":"lab-honeypot","title":"Run a Cowrie SSH honeypot and block attackers","track":"Foundations","level":"Intermediate","minutes":150,"cost":"Free","summary":"Run the Cowrie SSH honeypot in Docker on the isolated lab network, restrict the real SSH service, play the attacker from another lab VM, analyze Cowrie's JSON logs with jq, and block the source IP at the host and at the container.","stepCount":12},{"id":"lab-ssh-mfa","title":"Password policy, SSH MFA and breached-password checks","track":"Foundations","level":"Intermediate","minutes":120,"cost":"Free","summary":"Enforce a password policy with pam_pwquality, require an SSH key plus a TOTP code with libpam-google-authenticator, test failure and recovery, set up a password manager, and check a password against Have I Been Pwned without sending it.","stepCount":12},{"id":"lab-risk-register","title":"Build a risk register and heat map for a small business","track":"GRC & architecture","level":"Beginner","minutes":150,"cost":"Free","summary":"Run a real risk assessment for the 11:Eleven lounge: inventory assets, pair threats with vulnerabilities, score them on a 5x5 heat map, work out SLE and ALE for three risks, and choose a treatment, owner and residual risk for each. You finish with a reusable risk register spreadsheet.","stepCount":12},{"id":"lab-bia-backup","title":"Business impact analysis and a tested restic backup","track":"GRC & architecture","level":"Intermediate","minutes":150,"cost":"Free","summary":"Run a business impact analysis for the lounge to set RTO, RPO and MTD for its critical processes, then build real 3-2-1 backups of a lab folder with restic (encrypted, with a retention policy and a systemd timer) and prove them with a timed restore.","stepCount":12},{"id":"lab-policy-writing","title":"Write a policy set mapped to NIST CSF 2.0","track":"GRC & architecture","level":"Beginner","minutes":180,"cost":"Free","summary":"Write three short policies for the lounge (acceptable use, password/MFA, incident response), plus one supporting standard and one procedure, with an approval workflow and exception process, and map each to the NIST CSF 2.0 functions.","stepCount":11},{"id":"lab-data-classification","title":"Classify data and encrypt it at rest and in transit","track":"GRC & architecture","level":"Beginner","minutes":120,"cost":"Free","summary":"Define a four-level data classification scheme, classify the lounge's data, write handling, retention and disposal rules (NIST SP 800-88 clear/purge/destroy), sketch a DLP rule, then apply encryption at rest with a LUKS container and gpg and check TLS in transit.","stepCount":11},{"id":"lab-cloud-iam","title":"Secure a new AWS account: root MFA, least privilege, logging","track":"GRC & architecture","level":"Intermediate","minutes":150,"cost":"Free if you follow the steps and clean up (AWS free tier; set a $1 budget alert FIRST)","summary":"Lock down a brand-new AWS account the way a cloud security engineer would: a $1 budget alert, root MFA, an admin identity in IAM Identity Center, a least-privilege policy for one S3 bucket, Block Public Access and encryption, CloudTrail and IAM Access Analyzer — then delete everything.","stepCount":13},{"id":"lab-appsec-zap","title":"Scan your own OWASP Juice Shop with ZAP and map to the OWASP Top 10","track":"GRC & architecture","level":"Intermediate","minutes":120,"cost":"Free","summary":"Run the deliberately vulnerable OWASP Juice Shop on localhost, scan it with ZAP's baseline (and optionally full) scan, triage the alerts, and map five findings to OWASP Top 10 (2021) categories with the correct developer fix for each.","stepCount":11},{"id":"lab-threat-model","title":"Threat model the lounge's reservation site with OWASP Threat Dragon","track":"GRC & architecture","level":"Intermediate","minutes":120,"cost":"Free","summary":"Draw a data flow diagram of 11:Eleven's online reservation system in OWASP Threat Dragon, mark trust boundaries, apply STRIDE to each element, rate and mitigate the threats, and export the model and a report.","stepCount":11},{"id":"lab-iam-sso","title":"Run identity and access management with Keycloak (RBAC, MFA, OIDC)","track":"GRC & architecture","level":"Intermediate","minutes":150,"cost":"Free","summary":"Stand up Keycloak in dev mode, build a realm for the lounge with users, groups and roles, enforce TOTP MFA, connect a sample OIDC app, run a joiner-mover-leaver scenario and finish with an access review.","stepCount":12},{"id":"lab-secure-sdlc","title":"Shift left: SAST, SCA and secret scanning in CI","track":"GRC & architecture","level":"Intermediate","minutes":150,"cost":"Free","summary":"Scan OWASP NodeGoat with Semgrep CE (SAST), npm audit and Trivy (SCA) and gitleaks (secrets), fix two findings, and wire the scans into a GitHub Actions workflow on your own repository.","stepCount":11},{"id":"lab-container-security","title":"Harden a Docker container and measure the difference with Trivy","track":"GRC & architecture","level":"Intermediate","minutes":120,"cost":"Free","summary":"Build a small web app image on a full base, scan it with Trivy, rebuild it on slim and distroless bases, run it as non-root with a read-only filesystem, no capabilities and resource limits, then rescan and compare. Finish with a docker-bench-security audit.","stepCount":11},{"id":"lab-vendor-risk","title":"Third-party risk review of a real SaaS vendor","track":"GRC & architecture","level":"Beginner","minutes":150,"cost":"Free","summary":"Assess a real vendor the lounge would use (a reservation platform or POS/payment provider) from public evidence: trust page, SOC 2 / ISO 27001 / PCI status, data processing terms and breach history. Fill a short questionnaire, rate the risk and list the contract clauses to request.","stepCount":11},{"id":"lab-dns-bind","title":"Run your own DNS server and troubleshoot it with dig and tcpdump","track":"Networking","level":"Intermediate","minutes":180,"cost":"Free (BIND 9 and dig from the Ubuntu archive)","summary":"Stand up a BIND 9 authoritative and recursive server for a private lab.internal zone, query every common record type with dig, trace a real delegation, see DNSSEC validation pass and fail, lock down zone transfers, and diagnose NXDOMAIN, SERVFAIL, REFUSED and timeout faults from the packets.","stepCount":13},{"id":"lab-auditd","title":"Monitor a Linux server with auditd rules and reports","track":"Blue team","level":"Intermediate","minutes":150,"cost":"Free","summary":"Install the Linux Audit framework, write rules that watch identity files, sudoers, SSH config, root commands run by real users and kernel module loads, generate the activity yourself, then find it with ausearch and aureport, forward it to syslog and lock the rules so an attacker cannot quietly turn them off.","stepCount":11},{"id":"lab-ad-gpo","title":"Build an Active Directory domain and enforce a Group Policy baseline","track":"Foundations","level":"Intermediate","minutes":300,"cost":"Free (Windows Server 2022 180-day evaluation and your Windows 11 Enterprise evaluation VM)","summary":"Promote a Windows Server evaluation VM to a domain controller, build an OU structure, join your Windows client, then push a workstation security baseline with Group Policy: domain password and lockout policy, firewall, LLMNR off, SMB signing, script block logging, Windows LAPS for local admin passwords, and advanced audit policy. Prove every setting applied with gpresult and compare it with Microsoft's baseline.","stepCount":12},{"id":"lab-wireguard-vpn","title":"Build site-to-site and remote-access VPNs with WireGuard","track":"Networking","level":"Intermediate","minutes":150,"cost":"Free","summary":"Connect two Ubuntu 'sites' with an encrypted WireGuard tunnel, route each site's LAN over it, prove the traffic is encrypted on the wire and cleartext inside the tunnel, see cryptokey routing drop traffic that is not allowed, then add your Windows VM as a split-tunnel remote-access client and revoke it.","stepCount":12},{"id":"lab-net-monitoring","title":"Centralize syslog, sync time with NTP and poll devices with SNMPv3","track":"Networking","level":"Intermediate","minutes":180,"cost":"Free","summary":"Turn one Ubuntu VM into a lab time server and central log collector: serve NTP with chrony, receive logs over TCP with rsyslog into per-host files, test store-and-forward when the collector goes down, set log rotation and retention, and poll the other VM with authenticated, encrypted SNMPv3 while proving SNMPv1/v2c is off.","stepCount":12},{"id":"lab-db-failover","title":"DR drill: fail over a replicated PostgreSQL database and measure RPO and RTO","track":"GRC & architecture","level":"Advanced","minutes":240,"cost":"Free","summary":"Set DR objectives for a small reservations database, build PostgreSQL 16 streaming replication between two Ubuntu VMs, run a live write workload, pull the plug on the primary, promote the standby, and measure the real recovery point and recovery time against your targets. Then rebuild the old primary as the new standby and write the after-action report.","stepCount":13},{"id":"lab-cloud-posture","title":"Audit your AWS account's security posture with Prowler and fix the findings","track":"GRC & architecture","level":"Intermediate","minutes":180,"cost":"Free (AWS free tier; the scan is read-only API calls, and a $1 budget alert should already exist from lab-cloud-iam)","summary":"Create a read-only auditor identity with the AWS SecurityAudit and ViewOnlyAccess policies, plant one harmless misconfiguration, run the open-source Prowler scanner against your own account and against the CIS AWS Foundations Benchmark, triage the results, remediate the top findings with the AWS CLI, rescan to prove the fix, and document accepted risks.","stepCount":11},{"id":"lab-controls-audit","title":"Run an internal audit against the CIS Controls IG1 and write the audit report","track":"GRC & architecture","level":"Intermediate","minutes":240,"cost":"Free (CIS Controls v8.1 download with a free CIS registration)","summary":"Plan and perform a small internal audit of your own home lab against CIS Critical Security Controls v8.1 Implementation Group 1: write the scope and criteria, build workpapers, collect command-line evidence for inventory, accounts, patching, logging, malware defenses and backups, hash the evidence, rate findings in condition-criteria-cause-effect form and deliver an audit report with a management response.","stepCount":11},{"id":"lab-apparmor-mac","title":"Enforce mandatory access control with AppArmor profiles","track":"Foundations","level":"Intermediate","minutes":120,"cost":"Free","summary":"See the difference between discretionary and mandatory access control on Ubuntu: inspect the AppArmor profiles already protecting your server, write a profile that confines a program to one directory, watch it block even root, use complain mode and aa-logprof to refine it, and apply a deny rule.","stepCount":10},{"id":"lab-radius-aaa","title":"AAA with FreeRADIUS: RADIUS, PEAP and dynamic VLANs tested with eapol_test","track":"Networking","level":"Advanced","minutes":180,"cost":"Free","summary":"Build a FreeRADIUS server that authenticates users for switches and Wi-Fi, returns a VLAN assignment, and logs accounting records. Test it the way network engineers do without hardware: radtest for PAP, eapol_test to run a full 802.1X PEAP-MSCHAPv2 exchange, a wrong-CA test to see why clients must validate the server certificate, and radclient for accounting.","stepCount":12},{"id":"lab-frr-ospf-multiarea","title":"Multi-area OSPF, stub areas and route redistribution with FRRouting","track":"Networking","level":"Intermediate","minutes":180,"cost":"Free (Docker, containerlab and the FRRouting container image, all open source)","summary":"Build a four-router, three-area OSPF network out of FRRouting containers with containerlab, read the link-state database (LSA types 1, 2, 3, 4 and 5), summarize an area at its ABR, redistribute static routes through a prefix-list and route-map, turn an area into a totally stubby area, and diagnose an MTU mismatch that leaves neighbors stuck in ExStart.","stepCount":12},{"id":"lab-frr-bgp","title":"eBGP and iBGP between two autonomous systems with FRRouting","track":"Networking","level":"Advanced","minutes":210,"cost":"Free (containerlab and FRRouting containers on your own VM)","summary":"Connect a dual-homed enterprise (AS 65001, two edge routers running iBGP over an OSPF underlay) to a provider (AS 65002) with eBGP, see FRR refuse to exchange routes until a policy exists, write prefix-list and route-map filters that drop a leaked prefix, steer traffic both ways with local preference and AS-path prepending, then test failover and fix a classic iBGP next-hop fault.","stepCount":11},{"id":"lab-vrrp-failover","title":"First-hop redundancy with VRRP (keepalived) and failover testing","track":"Networking","level":"Intermediate","minutes":150,"cost":"Free (keepalived, Alpine Linux and containerlab)","summary":"Give a LAN a virtual default gateway shared by two routers using VRRPv3 with keepalived, watch the advertisements and gratuitous ARPs on the wire, then fail the master three different ways (uplink loss tracked by a health script, LAN link loss, a frozen router) and measure how many packets each failure costs.","stepCount":11},{"id":"lab-ipv6-dual-stack","title":"Build and troubleshoot a dual-stack IPv6 network: SLAAC, DHCPv6 and OSPFv3","track":"Networking","level":"Intermediate","minutes":200,"cost":"Free (FRRouting, dnsmasq and Alpine Linux containers)","summary":"Run IPv4 and IPv6 side by side: one LAN configured by SLAAC with RDNSS, another by stateful DHCPv6, routed with OSPFv2 and OSPFv3 to a dual-stack server. Read router advertisements, EUI-64 addresses and neighbor discovery, see which protocol applications prefer, then troubleshoot four classic IPv6 faults: missing RAs, blocked ICMPv6, a missing IPv6 route and duplicate address detection.","stepCount":13},{"id":"lab-qos-tc","title":"QoS on Linux: shaping, DSCP marking and prioritization with tc and iperf3","track":"Networking","level":"Intermediate","minutes":150,"cost":"Free (iproute2 tc, iptables and iperf3 on your Ubuntu VM)","summary":"Build a client-router-server path out of Linux network namespaces, emulate a 20 Mbit/s WAN link with 40 ms of latency, measure bufferbloat under load, fix it with fq_codel, then mark traffic with DSCP (EF, CS1), build an HTB class hierarchy that prioritizes voice over bulk traffic, enforce a trust boundary, and prove every result with iperf3, ping and tc counters.","stepCount":11},{"id":"lab-junos-cli","title":"Junos CLI fundamentals: commit model, rollback, interfaces, static routes and routing policy","track":"Networking","level":"Beginner","minutes":180,"cost":"Free (Juniper vLabs with a free Juniper account, or the free vJunos-router image on your own KVM host)","summary":"Learn Junos the way JNCIA tests it: operational versus configuration mode, the candidate configuration and commit, commit confirmed as a safety net, rollback, interfaces and loopbacks, static routes and route preference, OSPF, a routing policy that exports only approved static routes, and a firewall filter that protects the routing engine.","stepCount":11},{"id":"lab-aws-vpc","title":"AWS VPC networking: subnets, route tables, security groups vs NACLs, peering and flow logs","track":"Networking","level":"Intermediate","minutes":180,"cost":"Low if you clean up the same day: free-tier-eligible EC2 instances, a few cents of S3 and flow-log delivery. Public IPv4 addresses are billed hourly (about $0.005 per hour each) unless your free tier covers them. Do NOT create a NAT gateway: it costs about $0.045 per hour plus data processing (over $30 a month) even when idle.","summary":"Build two VPCs with the AWS CLI: public and private subnets, an internet gateway and route tables, a bastion host and a private instance, then prove that security groups are stateful and NACLs are stateless, use a NACL deny rule, peer the VPCs and fix routing so they can talk, read VPC flow logs from S3 including rejected internet scans, and tear it all down in dependency order.","stepCount":11},{"id":"lab-wifi-survey","title":"Wi-Fi site survey, channel plan and written design for your home or office","track":"Networking","level":"Intermediate","minutes":240,"cost":"Free (built-in OS tools, iperf3, diagrams.net; optionally a free survey app such as the free edition of NetSpot or the open-source WiFiAnalyzer for Android)","summary":"Survey a real space the way a wireless engineer does: write requirements, draw a floor plan to scale, run a passive scan of every nearby network, walk a grid recording RSSI, noise and link rate, run active throughput tests with iperf3, build a heat map, then produce a channel, width and power plan, apply it to your own access point, re-survey, and write it up as a design document.","stepCount":12},{"id":"lab-subnetting","title":"Plan and verify a VLSM and IPv6 addressing scheme","track":"Networking","level":"Beginner","minutes":90,"cost":"Free","summary":"Split 10.10.0.0/22 into right-sized subnets for a small office, plan matching IPv6 /64s, check every answer with ipcalc and sipcalc, then apply one subnet to your lab VMs with netplan and prove it works.","stepCount":12},{"id":"lab-wireshark-basics","title":"Capture and analyze traffic with Wireshark and tshark","track":"Networking","level":"Beginner","minutes":90,"cost":"Free","summary":"Capture traffic between your lab VMs, find a TCP three-way handshake, compare plain HTTP with HTTPS, read DNS, and use display filters, Follow TCP Stream, statistics and object export. Then repeat the key steps with tshark on the command line.","stepCount":12},{"id":"lab-nmap-discovery","title":"Discover hosts and build a service inventory with Nmap","track":"Networking","level":"Beginner","minutes":90,"cost":"Free","summary":"Use Nmap on your isolated lab to find live hosts, list open ports and service versions, save results in machine-readable formats, confirm them against the target's own view, shut down an unneeded service and prove it is gone with a rescan.","stepCount":12},{"id":"lab-pt-vlans","title":"VLANs, trunks and router-on-a-stick in Packet Tracer","track":"Networking","level":"Beginner","minutes":90,"cost":"Free (Cisco Packet Tracer with a free Networking Academy account)","summary":"Build two switches and a router in Cisco Packet Tracer, split users into Staff and Guest VLANs, connect the switches with an 802.1Q trunk using a dedicated native VLAN, and route between VLANs with router-on-a-stick.","stepCount":12},{"id":"lab-pt-ospf","title":"Single-area OSPFv2 with troubleshooting in Packet Tracer","track":"Networking","level":"Intermediate","minutes":90,"cost":"Free (Cisco Packet Tracer with a free Networking Academy account)","summary":"Connect three routers in a triangle, run single-area OSPFv2 with fixed router IDs and passive LAN interfaces, advertise a default route, verify neighbors and routes, then break the network twice (hello timer, area mismatch) and fix it.","stepCount":13},{"id":"lab-pt-acl-nat","title":"ACLs and PAT to an ISP in Packet Tracer","track":"Networking","level":"Intermediate","minutes":120,"cost":"Free (Cisco Packet Tracer with a free Networking Academy account)","summary":"Extend your VLAN lab with a server VLAN and an ISP router. Write an extended ACL that lets the guest VLAN reach the internal web server but nothing else on the server subnet, a standard ACL that limits SSH to staff, and PAT so every VLAN reaches the internet through one public address.","stepCount":12},{"id":"lab-pt-l2-security","title":"Switch security: port security, DHCP snooping, DAI and BPDU guard","track":"Networking","level":"Intermediate","minutes":120,"cost":"Free (Cisco Packet Tracer; Cisco Modeling Labs for any feature your Packet Tracer build does not support)","summary":"Harden an access switch: limit MACs per port with sticky port security, block a rogue DHCP server with DHCP snooping, stop ARP spoofing with Dynamic ARP Inspection, err-disable ports that receive BPDUs, and park unused ports in a shut-down black-hole VLAN.","stepCount":13},{"id":"lab-network-troubleshooting","title":"Troubleshoot real network faults with the CompTIA method","track":"Networking","level":"Beginner","minutes":120,"cost":"Free","summary":"Break DNS, the default gateway, IP addressing and DHCP on your lab VMs one at a time, then find and fix each fault using the seven-step CompTIA troubleshooting method and standard Linux and Windows tools, writing a ticket for each.","stepCount":12},{"id":"lab-firewall-pfsense","title":"Build a default-deny lab firewall with pfSense","track":"Networking","level":"Intermediate","minutes":150,"cost":"Free (pfSense Community Edition)","summary":"Run pfSense CE as your lab's firewall with WAN, LAN and DMZ interfaces. Replace allow-all with explicit default-deny rules, let the LAN reach only the DMZ web server's web ports using aliases, log denied traffic, test with curl and nc, and read the firewall log.","stepCount":12},{"id":"lab-wifi-audit","title":"Audit and harden your home Wi-Fi like a network admin","track":"Networking","level":"Beginner","minutes":75,"cost":"Free","summary":"Review your own router's settings (firmware, WPA3, WPS, admin credentials, remote management, guest isolation), survey nearby channels and signal strength with built-in tools, make the fixes, and write it up as an audit report.","stepCount":12},{"id":"lab-network-automation","title":"Network automation with Python, REST APIs, Netmiko and Ansible","track":"Networking","level":"Intermediate","minutes":150,"cost":"Free (Cisco DevNet Sandbox or Cisco Modeling Labs Free are optional)","summary":"Set up a Python virtual environment, parse JSON, call a free read-only REST API, pull and change configuration on a Cisco IOS XE device with Netmiko, then use Ansible to push an idempotent change to your Ubuntu VM and show the diff.","stepCount":12},{"id":"lab-entra-conditional-access","title":"Administer Microsoft Entra ID: users, groups, MFA and Conditional Access","track":"GRC & architecture","level":"Intermediate","minutes":240,"cost":"Free to low cost: a dedicated Entra ID tenant (created with an Azure free account) plus a 30-day Microsoft Entra ID P2 trial, which Conditional Access and sign-in log export need. The trial can ask for a payment method and can convert to paid, so turn off recurring billing on the day you start it.","summary":"In a lab tenant you own, create users and a dynamic group with Microsoft Graph PowerShell, add an excluded break-glass account, register MFA, then build Conditional Access policies in report-only mode, read their impact in the sign-in logs and the What If tool, and switch them on for a pilot group.","stepCount":12},{"id":"lab-entra-pim-reviews","title":"Just-in-time admin with Entra PIM and access reviews","track":"GRC & architecture","level":"Advanced","minutes":180,"cost":"Free within the 30-day Microsoft Entra ID P2 trial from lab-entra-conditional-access (PIM and access reviews need P2 or Microsoft Entra ID Governance). Keep recurring billing off.","summary":"Find standing privileged role holders, convert an administrator to an eligible Privileged Identity Management (PIM) assignment with MFA, justification, approval and a time limit, activate the role just in time, read the PIM audit trail, then run an access review of a group and a privileged role and apply the results.","stepCount":11},{"id":"lab-sentinel-kql","title":"Hunt with KQL and handle an incident in Microsoft Sentinel","track":"Blue team","level":"Intermediate","minutes":240,"cost":"Free for about a month if you stay small: new Sentinel workspaces get a 31-day free trial (up to 10 GB/day), Azure Activity data is free to ingest, and you set a 0.5 GB daily cap. After the trial, ingestion and retention are billed, so delete the workspace at the end and set an Azure budget alert first.","summary":"Create a Log Analytics workspace with a daily cap, enable Microsoft Sentinel, connect Azure Activity and Entra ID logs, write KQL hunting queries, build a scheduled analytics rule with entity mapping, trigger it with a harmless test change, investigate and close the incident, then delete everything.","stepCount":11},{"id":"lab-defender-asr","title":"Harden Microsoft Defender Antivirus and test attack surface reduction rules","track":"Blue team","level":"Intermediate","minutes":150,"cost":"Free (Microsoft Defender Antivirus is built into Windows 11 and Windows Server). The optional Defender for Endpoint portal step needs a trial license.","summary":"On your own Windows VM, check Defender's health, raise cloud protection and PUA blocking, turn on attack surface reduction (ASR) rules, network protection and controlled folder access in audit mode, trigger an ASR audit event with a harmless WMI command and a detection with the EICAR test file, read the event log, then enforce one rule and prove it blocks.","stepCount":11},{"id":"lab-azure-security-baseline","title":"Build an Azure security baseline: Key Vault, managed identity, NSGs, Defender for Cloud and Policy","track":"GRC & architecture","level":"Intermediate","minutes":210,"cost":"Low cost: an Azure free account covers a Standard_B1s VM (free-tier hours for eligible accounts) and Key Vault operations cost fractions of a cent. Use only the free Foundational CSPM tier of Defender for Cloud; do not enable paid Defender plans. Set a budget alert first and delete the resource group the same day.","summary":"Create a Key Vault with RBAC and a network firewall, give a VM with no public IP a managed identity that reads a secret without any stored credentials, lock the network down with an NSG and a service endpoint, review Defender for Cloud's free recommendations and secure score, enforce an Azure Policy, add a resource lock, then clean up.","stepCount":11},{"id":"lab-ngfw-policy","title":"Design next-generation firewall policy with OPNsense and map it to PAN-OS and FortiOS","track":"Blue team","level":"Advanced","minutes":270,"cost":"Free (OPNsense Community Edition, the Zenarmor Free edition plugin and Suricata with the free ET Open rules)","summary":"Build a three-zone OPNsense firewall (WAN, LAN, DMZ), write zone-based rules with aliases, add application and web-category control with Zenarmor, run Suricata as an inline IPS with a benign test signature, study how TLS inspection works, and translate every object you built into Palo Alto PAN-OS and Fortinet FortiOS terms.","stepCount":12},{"id":"lab-ipsec-site-to-site","title":"Build a site-to-site IPsec VPN with security profiles on OPNsense","track":"Blue team","level":"Advanced","minutes":240,"cost":"Free (two OPNsense Community Edition VMs). Optional: a FortiGate-VM permanent trial from a free Fortinet account, which has tight limits on interfaces, policies and routes.","summary":"Connect two lab sites with a policy-based IKEv2 IPsec tunnel between two OPNsense firewalls, choose strong proposals, restrict what may cross the tunnel with firewall rules, inspect tunnel traffic with Suricata, break and fix the tunnel from the logs, and map the whole build to FortiOS phase1/phase2 and PAN-OS IKE gateway terms.","stepCount":11},{"id":"lab-git-workflow","title":"Git workflow: branches, pull requests and a real merge conflict","track":"Software engineering","level":"Beginner","minutes":120,"cost":"Free (git and a free GitHub account)","summary":"Set up git properly, work on feature branches, create and resolve a merge conflict by hand, then do the same on GitHub: push a branch, open a pull request with the gh CLI, review it, protect main with a ruleset, and undo mistakes safely with revert, restore and stash.","stepCount":11},{"id":"lab-python-project","title":"A Python project done right: venv, packaging, pytest and ruff","track":"Software engineering","level":"Beginner","minutes":150,"cost":"Free","summary":"Build a small Python package the way professionals do: an isolated virtual environment, a src layout with pyproject.toml, a class with a custom exception, pytest tests with fixtures and parametrize, coverage, ruff linting and formatting, a command-line entry point, and a wheel you install into a clean environment.","stepCount":11},{"id":"lab-java-build-test","title":"Java project with Maven, Gradle and JUnit 5 tests","track":"Software engineering","level":"Intermediate","minutes":180,"cost":"Free (Eclipse Temurin JDK, Maven, Gradle, JUnit are open source)","summary":"Install a current JDK with SDKMAN, build a small inventory library in modern Java (records, sealed interfaces, switch patterns, streams, a custom exception), drive it with JUnit 5 tests including parameterized ones, measure coverage with JaCoCo, package a runnable jar, then build the same code with Gradle and compare.","stepCount":10},{"id":"lab-rest-api","title":"Build, test and document a REST API with FastAPI and OpenAPI","track":"Software engineering","level":"Intermediate","minutes":180,"cost":"Free","summary":"Build the Shelf book API with FastAPI, Pydantic validation and SQLAlchemy (SQLite locally, Postgres later), using correct HTTP methods and status codes, pagination and a health endpoint. Test it with pytest and TestClient, explore the generated OpenAPI docs, export and lint the spec, and call the API with curl.","stepCount":9},{"id":"lab-docker-compose-app","title":"Containerize the API: multi-stage Dockerfile, non-root user and Compose with Postgres","track":"Software engineering","level":"Intermediate","minutes":150,"cost":"Free (Docker Engine and public images)","summary":"Package the Shelf API into a small multi-stage image that runs as a non-root user with a health check, use layer caching well, then run it with Docker Compose next to PostgreSQL with a health-gated startup, a named volume, environment-based configuration and no database port exposed. Finish by tagging a versioned image for the next labs.","stepCount":11},{"id":"lab-github-actions-ci","title":"CI pipeline with GitHub Actions: lint, test matrix, Postgres service and image build","track":"Software engineering","level":"Intermediate","minutes":150,"cost":"Free (GitHub Actions minutes are free on public repositories; private repositories include a monthly free allowance)","summary":"Put the Shelf API under continuous integration: a workflow that lints with ruff, runs pytest across three Python versions with pip caching, runs integration tests against a real Postgres service container, uploads test reports, and builds the Docker image with Buildx layer caching, pushing to GitHub Container Registry only from main. Then make the checks required and watch a broken pull request get blocked.","stepCount":10},{"id":"lab-kubernetes-kind","title":"Deploy the API to Kubernetes with kind: probes, config, secrets and rolling updates","track":"Software engineering","level":"Advanced","minutes":210,"cost":"Free (kind runs Kubernetes inside Docker on your VM)","summary":"Create a local multi-node Kubernetes cluster with kind, load your Shelf API image, and deploy it with Postgres using a Namespace, ConfigMap, Secret, PersistentVolumeClaim, Deployments with startup, readiness and liveness probes, resource limits and a restricted security context, and ClusterIP Services. Then roll out a new version, break a rollout on purpose, roll back and troubleshoot with describe, logs and events.","stepCount":11},{"id":"lab-lambda-api","title":"Serverless API on AWS Lambda and API Gateway (Free Tier, with cleanup)","track":"Software engineering","level":"Intermediate","minutes":150,"cost":"Free or a few cents if you follow the steps and clean up (Lambda has an always-free monthly allowance; API Gateway HTTP API charges per million requests after any free-tier or credit allowance on your account). Set a budget alert first.","summary":"Build a Python Lambda function from the CLI: a least-privilege execution role, environment variables, a test invoke and CloudWatch Logs, then front it with an API Gateway HTTP API, add the resource-based permission, throttle the stage, publish versions with a live alias, trace an error through the logs, compare with an AWS SAM template, and delete everything.","stepCount":11},{"id":"lab-terraform-docker","title":"Infrastructure as code with Terraform: providers, modules, state and workspaces","track":"Software engineering","level":"Intermediate","minutes":180,"cost":"Free (Terraform CLI with the Docker, random and local providers; nothing in the cloud)","summary":"Provision the Shelf API stack (network, volume, Postgres and API containers) on your own Docker host with Terraform. Write variables with validation, outputs and a reusable module, run the full init, fmt, validate, plan, apply and destroy workflow, inspect and protect state, detect and fix drift, import an existing resource, and run a second copy of the stack with workspaces.","stepCount":11},{"id":"lab-helpdesk-tickets","title":"Help desk simulation: build a troubleshooting kit and close six Windows tickets","track":"Systems administration","level":"Beginner","minutes":210,"cost":"Free (Windows evaluation VM, built-in tools and Sysinternals)","summary":"Build a technician's troubleshooting kit, stage six realistic faults on your own Windows VM (stopped print spooler, bad DNS server, a user whose files 'vanished' because of a broken profile, a full system disk, a disabled network driver and a CPU-hogging startup item), then work each one as a ticket with the CompTIA troubleshooting method and write a knowledge-base article.","stepCount":11},{"id":"lab-windows-deployment","title":"Deploy Windows 11 with an answer file, a golden image and user state migration","track":"Systems administration","level":"Intermediate","minutes":300,"cost":"Free (Windows 11 Enterprise evaluation, Windows ADK and WinPE add-on); needs about 120 GB of free disk on your host","summary":"Install the Windows ADK, write an autounattend.xml and a provisioning script for a hands-off Windows 11 install, sysprep and capture a reference image with DISM from WinPE, apply it to a blank VM with diskpart and bcdboot, then move a user's documents and settings from an old PC to the new one with USMT.","stepCount":10},{"id":"lab-linux-storage-lvm","title":"Linux storage: partitions, LVM, filesystems, swap and fstab on VM disks","track":"Systems administration","level":"Intermediate","minutes":150,"cost":"Free (two small extra virtual disks on your Ubuntu VM)","summary":"Add two virtual disks to your Ubuntu server, partition them with GPT, build XFS and ext4 filesystems, mount them persistently by UUID, create an LVM volume group, grow a logical volume while it is in use, shrink one safely, add swap, take an LVM snapshot for a consistent backup, and catch a broken fstab entry before it stops the server booting.","stepCount":11},{"id":"lab-systemd-services","title":"Systemd services, timers and journald: build, harden and fix a failing service","track":"Systems administration","level":"Intermediate","minutes":150,"cost":"Free (systemd and Python 3 already on Ubuntu Server)","summary":"Write your own systemd service that runs as an unprivileged user, give it a restart policy and a drop-in override with sandboxing, replace a cron job with a timer, make the journal persistent and size-limited, then diagnose four staged failures (bad ExecStart, missing directory, port conflict and start-limit-hit) from systemctl and journalctl output alone.","stepCount":11},{"id":"lab-package-patching","title":"Package management and patching on AlmaLinux and Ubuntu: repos, updates and rollback","track":"Systems administration","level":"Intermediate","minutes":180,"cost":"Free (AlmaLinux 9 and Ubuntu Server 24.04, both free to download and update)","summary":"Build an AlmaLinux 9 VM next to your Ubuntu server and learn both package worlds side by side: query and verify packages with rpm/dnf and dpkg/apt, add EPEL and a signed third-party apt repository, build your own local dnf repository, assess and apply security updates, roll a change back with dnf history, pin versions, decide when a reboot is needed and switch on automatic security updates.","stepCount":11},{"id":"lab-powershell-admin","title":"PowerShell administration: bulk users, services, scheduled tasks and remote management","track":"Systems administration","level":"Intermediate","minutes":180,"cost":"Free (PowerShell 7, Windows evaluation VMs, PSScriptAnalyzer from the PowerShell Gallery)","summary":"Use PowerShell 7 the way a Windows admin does: work with objects in the pipeline, create users in bulk from a CSV, report and fix services, write a reusable health-check function with -WhatIf support, schedule it as a task, run it on a second machine over PowerShell remoting and CIM sessions, query event logs remotely, and lint your code with PSScriptAnalyzer.","stepCount":10},{"id":"lab-azure-admin","title":"Azure administration basics: resource groups, VNet, NSG, VM, storage, RBAC and cost control","track":"Systems administration","level":"Intermediate","minutes":180,"cost":"Free-account credit or free-tier services if used as described (read the current terms at azure.microsoft.com/free). A forgotten VM, public IP or disk keeps billing; set the budget alert first and delete the resource group the same day.","summary":"In your own Azure free account, set a budget alert first, then build a tagged resource group with a VNet and two subnets, an NSG that allows SSH only from your IP, a small Ubuntu VM with auto-shutdown, and a locked-down storage account. Learn why Owner cannot read blobs until you grant a data role, give a second user read-only access with RBAC, enforce an allowed-locations policy, read the activity log, and tear it all down.","stepCount":11},{"id":"lab-k8s-cluster-admin","title":"Kubernetes cluster administration with kubeadm: build, back up etcd, drain, upgrade and troubleshoot","track":"Systems administration","level":"Advanced","minutes":300,"cost":"Free (kubeadm, containerd and Flannel on two local Ubuntu VMs)","summary":"Build a two-node Kubernetes cluster with kubeadm on your own VMs, add a CNI plugin and a worker, back up etcd and restore it after a deliberate deletion, drain and cordon nodes for maintenance, upgrade the control plane and worker by one minor version, and fix a NotReady node and a broken control-plane static pod from the logs.","stepCount":12},{"id":"lab-postgres-dba","title":"PostgreSQL administration: roles, access control, backups, point-in-time restore and tuning","track":"Systems administration","level":"Intermediate","minutes":240,"cost":"Free (PostgreSQL 16 from the Ubuntu archive)","summary":"Run PostgreSQL 16 like a DBA: design group and login roles with least privilege, restrict network access in pg_hba.conf, load a benchmark database, take logical backups with pg_dump and prove them with a timed restore, set up WAL archiving and a base backup, recover to the moment before an accidental DELETE, then find a slow query with EXPLAIN ANALYZE, fix it with an index and measure the difference.","stepCount":12}], { index: true });
